let file = """{"version":3,"file":"useModalLiftedZIndex-C6lc2uEg.js","names":[],"sources":["../../src/composables/useModalLiftedZIndex.ts"],"sourcesContent":["import { ZIndex } from '@primeuix/utils/zindex'\nimport type { InjectionKey, Ref } from 'vue'\nimport { computed, inject } from 'vue'\n\nexport const overlayZIndexKey: InjectionKey<number> = Symbol('overlayZIndex')\n\n// Shared base for @primeuix's auto-incrementing 'modal' z-index counter.\nconst MODAL_BASE_Z_INDEX = 1700\n\n/**\n * Inline z-index style for body-portaled popover/menu content. Such content\n * keeps its static `z-1700` class unless a dialog that joined @primeuix's\n * auto-incrementing 'modal' counter (Reka and PrimeVue dialogs both do, via\n * `v-reka-z-index` or PrimeVue's mask) is open above it; then lift past that\n * dialog so the content isn't hidden behind the dialog or its scrim.\n */\nexport function useModalLiftedZIndex(open: Ref<boolean>) {\n  const parentZIndex = inject(overlayZIndexKey, 0)\n  return computed(() => {\n    if (!open.value) return undefined\n    const topZIndex = Math.max(ZIndex.getCurrent('modal'), parentZIndex)\n    return topZIndex >= MODAL_BASE_Z_INDEX\n      ? { zIndex: topZIndex + 1 }\n      : undefined\n  })\n}\n"],"mappings":"kJAIA,IAAa,EAAyC,OAAO,eAAe,EAGtE,EAAqB,KAS3B,SAAgB,qBAAqB,EAAoB,CACvD,IAAM,EAAe,EAAO,EAAkB,CAAC,EAC/C,OAAO,MAAe,CACpB,GAAI,CAAC,EAAK,MAAO,OACjB,IAAM,EAAY,KAAK,IAAI,EAAO,WAAW,OAAO,EAAG,CAAY,EACnE,OAAO,GAAa,EAChB,CAAE,OAAQ,EAAY,CAAE,EACxB,IAAA,EACN,CAAC,CACH"}"""

